    var columns = this._getExportColumns();
    var data = this._getExportData();
    var isTree = this.context.isTreeActive();
    var treeColumn = this.context.getTreeColumnField();

    var workbook = new window.ExcelJS.Workbook();
    var worksheet = workbook.addWorksheet(sheetName);

    // Define columns
